import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1]
    found = []
    best = 0
    for i in range(n):
        for j in range(i + 1, n):
            m = 0
            while j + m < n and s[i + m] == s[j + m]:
                m += 1
            if m > best:
                best = m
                found = [s[i:i + m]]
            elif m == best and m > 0:
                found.append(s[i:i + m])
    print(min(found) if best > 0 else -1)


main()
